import { useState } from "react";

export function OutputElement({
  a: initialA = {{a}},
  b: initialB = {{b}},
  accent = "{{accent}}",
  showFormula = {{showFormula}},
}) {
  const [a, setA] = useState(initialA);
  const [b, setB] = useState(initialB);
  return (
    <form style={{ width: 320, boxSizing: "border-box", font: "15px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, fontWeight: 600 }}>
        <input type="number" value={a} onChange={(e) => setA(Number(e.target.value))}
          style={{ width: 54, font: "14px system-ui, sans-serif", padding: "6px 8px", borderRadius: 6, border: "1.5px solid #24143030" }} /> +
        <input type="number" value={b} onChange={(e) => setB(Number(e.target.value))}
          style={{ width: 54, font: "14px system-ui, sans-serif", padding: "6px 8px", borderRadius: 6, border: "1.5px solid #24143030" }} /> =
        <output htmlFor="a b" style={{ fontWeight: 800, color: accent, fontSize: 18 }}>{a + b}</output>
      </div>
      {showFormula && <p style={{ margin: "12px 0 0", fontSize: 12, color: "#24143088" }}>The real <code>&lt;output&gt;</code> recalculates live as you edit the inputs.</p>}
    </form>
  );
}
